{
  "recommendation": "EcoCard",
  "why": "It has the strongest documented sign-up bonus: 2,000 sustainability points, redeemable at $0.01 per point for a $20 statement credit or checking-account deposit.",
  "requirements": {
    "eligible_spending": "$5,000 in eligible purchases",
    "time_limit": "Within the first month after account opening",
    "eligibility": "New customers with an account open and in good standing",
    "offer_window": "August 1, 2025 through December 15, 2025"
  },
  "additional_rewards": "The EcoCard earns 5 points per dollar on green purchases and 1 point per dollar on other purchases.",
  "important_exclusions": "Returns, chargebacks, disputed transactions, balance transfers, cash equivalents, and fees do not count toward the spending requirement.",
  "terms": {
    "annual_fee": "$50",
    "purchase_apr": "19.99% on carried balances"
  },
  "bottom_line": "If you can comfortably spend $5,000 in the first month and value points, the EcoCard is the best documented sign-up offer I found. Avoid spending extra or carrying a balance just to earn the bonus, since interest could outweigh its $20 value."
}
